import{_ as l,o,c as r,a2 as i}from"./chunks/framework.DGk0zlJw.js";const c=JSON.parse('{"title":"装机验收执行清单（71 条 · 2026-10-12）","description":"","frontmatter":{},"headers":[],"relativePath":"zh/acceptance-checklist.md","filePath":"zh/acceptance-checklist.md"}'),a={name:"zh/acceptance-checklist.md"};function e(n,t,s,g,h,d){return o(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="装机验收执行清单-71-条-·-2026-10-12" tabindex="-1">装机验收执行清单（71 条 · 2026-10-12） <a class="header-anchor" href="#装机验收执行清单-71-条-·-2026-10-12" aria-label="Permalink to &quot;装机验收执行清单（71 条 · 2026-10-12）&quot;">​</a></h1><blockquote><p>源头：<code>docs/mvp-issues.md</code>「装机对照清单」三类台账（已验 1 + 已修待验 17 + 未修 53 = <strong>71 条</strong>，2026-10-12 十一次整理修正原 51/68 加和漂移；批3-补47 增 2.17 后逐行重算）。 本版把每条展开为<strong>前置条件 / 验证步骤 / 预期结果</strong>三段式；每步都能照着做，每条都能单独回执。 带本地自动化证据的项在「附：本地自动化覆盖注记」标注了对应单测，真机只补 UI/交互半。</p></blockquote><h2 id="_0-通用准备-各条引用编号-不重复写" tabindex="-1">0. 通用准备（各条引用编号，不重复写） <a class="header-anchor" href="#_0-通用准备-各条引用编号-不重复写" aria-label="Permalink to &quot;0. 通用准备（各条引用编号，不重复写）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>编号</th><th>准备内容</th></tr></thead><tbody><tr><td><strong>E0 装包</strong></td><td>daily-build 最新绿跑下载 nightly 资产（zip + SHA256SUMS 核对一致），解压干净目录运行。<strong>版本门</strong>：2026-10-12 后的包（批3-补42 DSL、批3-补45 悬浮加宽、批3-补47 检查更新在此之后）才含新项；此前包测不到新项</td></tr><tr><td><strong>E1 日志</strong></td><td><code>%APPDATA%\\Beacon\\logs\\beacon-YYYYMMDD.log</code>；失败项附日志行取证</td></tr><tr><td><strong>E2 回执</strong></td><td>每条记「通过 / 失败+现象+截图或日志行」；通过即在 <code>docs/mvp-issues.md</code> 对应行注日期；失败只记现象不自修</td></tr><tr><td><strong>C-GH</strong></td><td>GitHub 连接（真实 PAT）+ <code>github.pull_requests</code>、<code>github.actions.runs</code> 组件各一（指向有 PR 与 Actions 活动的真实仓库）</td></tr><tr><td><strong>C-HTTP</strong></td><td>http 连接（任一可达 JSON 端点；局域网打包机或公共 echo 服务均可）</td></tr><tr><td><strong>C-MACHINE</strong></td><td>machine 连接（零凭据）</td></tr><tr><td><strong>C-HERALD</strong></td><td>自建 herald 实例连接（cuihairu/herald）</td></tr><tr><td><strong>C-MIMO</strong></td><td>小米 MiMo 连接 + 浏览器登录 platform.xiaomimimo.com 备用（F12 取 Cookie）</td></tr><tr><td><strong>C-JENKINS</strong></td><td>Jenkins 连接（公共匿名实例 <code>https://weekly.ci.jenkins.io</code> 即可，或自建）</td></tr><tr><td><strong>C-MOONSHOT</strong></td><td>Moonshot 开放平台 Key（platform.moonshot.cn，与 Kimi For Coding 不通用）</td></tr><tr><td><strong>C-DISCONNECT</strong></td><td>断网手段：关 Wi-Fi/拔网线；恢复手段同</td></tr><tr><td><strong>C-DPI</strong></td><td>200%/250% 缩放显示器（或 Windows 设置改缩放）；多屏则至少两块缩放不同的屏</td></tr></tbody></table><p>回执总口径：全部通过后 MVP 验收（B-803）即闭；录屏/截图归档 <code>docs/</code>。</p><hr><h2 id="_1-已验-1-条-留档不再执行" tabindex="-1">1. 已验（1 条，留档不再执行） <a class="header-anchor" href="#_1-已验-1-条-留档不再执行" aria-label="Permalink to &quot;1. 已验（1 条，留档不再执行）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项</th><th>结论</th></tr></thead><tbody><tr><td>悬浮透明度下限 0.4→0.2（批3-补10/补13⑤）</td><td>用户 2026-10-10 装机确认修好，保持别动</td></tr></tbody></table><hr><h2 id="_2-已修待验-17-条-装最新-nightly-重点看" tabindex="-1">2. 已修待验（17 条，装最新 nightly 重点看） <a class="header-anchor" href="#_2-已修待验-17-条-装最新-nightly-重点看" aria-label="Permalink to &quot;2. 已修待验（17 条，装最新 nightly 重点看）&quot;">​</a></h2><h3 id="_2-1-b-301-真实-pat-连接测试-成功-失败路径" tabindex="-1">2.1 B-301｜真实 PAT 连接测试 成功/失败路径 <a class="header-anchor" href="#_2-1-b-301-真实-pat-连接测试-成功-失败路径" aria-label="Permalink to &quot;2.1 B-301｜真实 PAT 连接测试 成功/失败路径&quot;">​</a></h3><ul><li><strong>前置</strong>：E0、E2；一个可 revoke 的真实 GitHub PAT。</li><li><strong>步骤</strong>：① 设置 → 连接 → 新建 GitHub，PAT 填错一位 → 「测试连接」；② PAT 留空 → 「测试连接」；③ 填正确 PAT → 「测试连接」；④ 换一个已 revoke 的 PAT → 「测试连接」。</li><li><strong>预期</strong>：①④ 明确报认证失败（不是「连接正常」）；② 走匿名请求、按匿名结果如实显示（不误报已认证）；③ 连接健康、rate-limit 头被感知。</li></ul><h3 id="_2-2-b-302-真实仓库-pr-手动验证-计数与亮黄" tabindex="-1">2.2 B-302｜真实仓库 PR 手动验证（计数与亮黄） <a class="header-anchor" href="#_2-2-b-302-真实仓库-pr-手动验证-计数与亮黄" aria-label="Permalink to &quot;2.2 B-302｜真实仓库 PR 手动验证（计数与亮黄）&quot;">​</a></h3><ul><li><strong>前置</strong>：E0、C-GH。</li><li><strong>步骤</strong>：① 添加 <code>github.pull_requests</code> 组件指向活跃仓库；② 对照 GitHub 网页上该仓库 Open PR 数；③ 刷新（托盘 Refresh All）；④ 制造一个新 PR 或关闭一个 PR 再刷新。</li><li><strong>预期</strong>：计数与网页一致；有 open PR 时亮黄、归零转绿；新增/关闭在 ≤1 刷新周期反映。</li></ul><h3 id="_2-3-b-302-真实仓库红-ci-判据" tabindex="-1">2.3 B-302｜真实仓库红 CI 判据 <a class="header-anchor" href="#_2-3-b-302-真实仓库红-ci-判据" aria-label="Permalink to &quot;2.3 B-302｜真实仓库红 CI 判据&quot;">​</a></h3><ul><li><strong>前置</strong>：同 2.2，且仓库需有红 CI 的 open PR（或在某 PR 上把 check 跑红）。</li><li><strong>步骤</strong>：① 观察 PR 卡摘要；② （可选）设置 <code>warn_on_red_ci</code> 开关再刷新对比。</li><li><strong>预期</strong>：红 CI PR 摘要出现「N red ci」段；304 续探后终态复用不再重复请求；开关关闭时不受红 CI 影响。</li></ul><h3 id="_2-4-b-303-真实-workflow-手动验证-成功-失败-运行中" tabindex="-1">2.4 B-303｜真实 workflow 手动验证（成功/失败/运行中） <a class="header-anchor" href="#_2-4-b-303-真实-workflow-手动验证-成功-失败-运行中" aria-label="Permalink to &quot;2.4 B-303｜真实 workflow 手动验证（成功/失败/运行中）&quot;">​</a></h3><ul><li><strong>前置</strong>：E0、C-GH（<code>github.actions.runs</code> 组件）。</li><li><strong>步骤</strong>：① 触发一次成功 run，等结束刷新；② 触发一次失败 run；③ 触发长 run（&gt;2 分钟）并在运行中刷新。</li><li><strong>预期</strong>：成功→绿、失败→红、运行中→黄且时长递增；16 分钟级卡住 run 时长格式正确（无负数/乱码）；坏 JSON 响应按 Degraded 明示不崩溃。</li></ul><h3 id="_2-5-b-303-真实-workflow-映射复核" tabindex="-1">2.5 B-303｜真实 workflow 映射复核 <a class="header-anchor" href="#_2-5-b-303-真实-workflow-映射复核" aria-label="Permalink to &quot;2.5 B-303｜真实 workflow 映射复核&quot;">​</a></h3><ul><li><strong>前置</strong>：同 2.4。</li><li><strong>步骤</strong>：对照 GitHub 网页 run 状态逐个核对 Beacon 卡面（queued/running/success/failure/cancelled）。</li><li><strong>预期</strong>：状态映射与网页一一对应；cancelled 不误判为 failure。</li></ul><h3 id="_2-6-批3-补8-小米控制台口径-glm-5h-主位" tabindex="-1">2.6 批3-补8｜小米控制台口径 + GLM 5h 主位 <a class="header-anchor" href="#_2-6-批3-补8-小米控制台口径-glm-5h-主位" aria-label="Permalink to &quot;2.6 批3-补8｜小米控制台口径 + GLM 5h 主位&quot;">​</a></h3><ul><li><strong>前置</strong>：E0、C-MIMO；GLM 真 Key 连接。</li><li><strong>步骤</strong>：① MiMo 连接录控制台 Cookie（F12 → 应用 → Cookies → <code>api-platform_ph</code> 整行粘贴）；② 刷新 MiMo 卡；③ GLM 卡观察主数值。</li><li><strong>预期</strong>：MiMo 显示套餐已用/总量/百分比（数据来自控制台 API 非「无额度口」占位）；GLM 主位为 5h 滚动窗百分比。</li></ul><h3 id="_2-7-批3-补9-17-18-23-悬浮框进度条-快捷面板底部" tabindex="-1">2.7 批3-补9/17/18/23｜悬浮框进度条 + 快捷面板底部 <a class="header-anchor" href="#_2-7-批3-补9-17-18-23-悬浮框进度条-快捷面板底部" aria-label="Permalink to &quot;2.7 批3-补9/17/18/23｜悬浮框进度条 + 快捷面板底部&quot;">​</a></h3><ul><li><strong>前置</strong>：E0；数值类组件（如 GLM/bigmodel 额度）且设置「数量悬浮窗」开。</li><li><strong>步骤</strong>：① 看悬浮 tile 进度条形态；② 用量调到 ≥80%（或改阈值）；③ 打开 Quick Panel 看 RECENT EVENTS 区。</li><li><strong>预期</strong>：进度条为 4 DIP 圆角条 + 「NN%」读数（默认形态）；≥80% 变黄、满格红；「池水」特效只在设置里自选才出现；RECENT EVENTS 在 Grid 内滚动、不把面板撑破。</li></ul><h3 id="_2-8-批3-补11-方舟额度用尽显示" tabindex="-1">2.8 批3-补11｜方舟额度用尽显示 <a class="header-anchor" href="#_2-8-批3-补11-方舟额度用尽显示" aria-label="Permalink to &quot;2.8 批3-补11｜方舟额度用尽显示&quot;">​</a></h3><ul><li><strong>前置</strong>：E0；方舟连接（Coding Plan）。自然用尽难触发，可临时把组件阈值调到极低模拟判级。</li><li><strong>步骤</strong>：① 等某窗（5h/周/月）用尽或用阈值模拟；② 收到 429 AccountQuotaExceeded 类响应时观察。</li><li><strong>预期</strong>：卡面显示「额度用尽（窗名，重置时间）」；429 耗尽特判按该窗已尽处理并带重置时间；普通限流 429 不翻转状态。</li></ul><h3 id="_2-9-批3-补12-通知规则接线" tabindex="-1">2.9 批3-补12｜通知规则接线 <a class="header-anchor" href="#_2-9-批3-补12-通知规则接线" aria-label="Permalink to &quot;2.9 批3-补12｜通知规则接线&quot;">​</a></h3><ul><li><strong>前置</strong>：E0；在设置 → 通知添加一条自定义规则（如某组件 Warning+ 时 Toast）。</li><li><strong>步骤</strong>：① 保存规则；② 制造满足条件的状态（如断对应连接或注入失败）；③ 再改规则重测。</li><li><strong>预期</strong>：自定义规则真实触发 Toast（此前接线前是空头支票）；规则修改后下次评估即生效，无需重启。</li></ul><h3 id="_2-10-批3-补13-ui-ux-审计-6-组可发现性修复-5透明度已验" tabindex="-1">2.10 批3-补13｜UI/UX 审计 6 组可发现性修复（⑤透明度已验） <a class="header-anchor" href="#_2-10-批3-补13-ui-ux-审计-6-组可发现性修复-5透明度已验" aria-label="Permalink to &quot;2.10 批3-补13｜UI/UX 审计 6 组可发现性修复（⑤透明度已验）&quot;">​</a></h3><ul><li><strong>前置</strong>：E0。</li><li><strong>步骤</strong>：逐组走查：① 动作独立页可发现；② 详情窗滚动区常驻（不靠滚动条自觉）；③ 设置表单压缩排布；④ 刷新档位中文标签；⑤ L2 tile 双列布局；⑥ 设置页整体截图留档。</li><li><strong>预期</strong>：各组均符合批3-补13 记录的设计；无按钮/区域「看不见」类问题。</li></ul><h3 id="_2-11-批3-补19-吸边细条无法恢复" tabindex="-1">2.11 批3-补19｜吸边细条无法恢复 <a class="header-anchor" href="#_2-11-批3-补19-吸边细条无法恢复" aria-label="Permalink to &quot;2.11 批3-补19｜吸边细条无法恢复&quot;">​</a></h3><ul><li><strong>前置</strong>：E0。</li><li><strong>步骤</strong>：① 拖胶囊/悬浮面板到屏幕边缘使其收成细条；② 鼠标悬停细条；③ 移开再悬停。</li><li><strong>预期</strong>：悬停细条展开为完整面板（不再死循环/无法恢复）；细条与展开面板同一 Place 数学，几何不跳变。</li></ul><h3 id="_2-12-批3-补20-5k-高缩放裁字-dpi" tabindex="-1">2.12 批3-补20｜5K/高缩放裁字（DPI） <a class="header-anchor" href="#_2-12-批3-补20-5k-高缩放裁字-dpi" aria-label="Permalink to &quot;2.12 批3-补20｜5K/高缩放裁字（DPI）&quot;">​</a></h3><ul><li><strong>前置</strong>：E0、C-DPI（200%/250%）。</li><li><strong>步骤</strong>：① 在 200% 缩放下打开详情窗；② 看胶囊与悬浮 tile 文字；③ 换 250% 重复。</li><li><strong>预期</strong>：详情窗按内容定尺寸、文字完整不裁；胶囊/悬浮框 DIP 布局正确（此前 5K 裁字根因是不 Resize 落固定物理像素）。</li></ul><h3 id="_2-13-批3-补20-拖动跟手-跨屏闪烁" tabindex="-1">2.13 批3-补20｜拖动跟手 + 跨屏闪烁 <a class="header-anchor" href="#_2-13-批3-补20-拖动跟手-跨屏闪烁" aria-label="Permalink to &quot;2.13 批3-补20｜拖动跟手 + 跨屏闪烁&quot;">​</a></h3><ul><li><strong>前置</strong>：E0、多屏（含高回报率鼠标更佳）。</li><li><strong>步骤</strong>：① 慢速拖动胶囊；② 快速甩动拖动；③ 拖跨两块不同 DPI 的屏。</li><li><strong>预期</strong>：全程跟手不爬行（起点绝对定位修复逐事件累加舍入）；跨 DPI 拖动中无重排闪烁（拖动中跳过 WM_DPICHANGED 重排）。</li></ul><h3 id="_2-14-批3-补21-moonshot-余额卡片" tabindex="-1">2.14 批3-补21｜Moonshot 余额卡片 <a class="header-anchor" href="#_2-14-批3-补21-moonshot-余额卡片" aria-label="Permalink to &quot;2.14 批3-补21｜Moonshot 余额卡片&quot;">​</a></h3><ul><li><strong>前置</strong>：E0、C-MOONSHOT。</li><li><strong>步骤</strong>：① 建 Moonshot 连接（platform.moonshot.cn Key）→ 测试连接；② 添加 <code>moonshot.balance</code> 组件；③ 对比网页余额；④ 把 <code>warn_below</code> 调到高于当前余额。</li><li><strong>预期</strong>：连接健康、余额金额与网页一致；余额 ≤ warn_below（默认 20）亮黄、≤ error_below（默认 5）红。</li></ul><h3 id="_2-15-批3-补22-拖动跨三屏跟手" tabindex="-1">2.15 批3-补22｜拖动跨三屏跟手 <a class="header-anchor" href="#_2-15-批3-补22-拖动跨三屏跟手" aria-label="Permalink to &quot;2.15 批3-补22｜拖动跨三屏跟手&quot;">​</a></h3><ul><li><strong>前置</strong>：E0、三块缩放不同的屏（没有三屏则两屏近似验证）。</li><li><strong>步骤</strong>：慢速拖胶囊依次跨过三块屏，每块屏停顿观察尺寸。</li><li><strong>预期</strong>：锚点始终跟随光标（物理像素口径），跨缩放屏无比例错乱、无尺寸突变。</li></ul><h3 id="_2-16-批3-补22-详情窗-200-仍裁字" tabindex="-1">2.16 批3-补22｜详情窗 200% 仍裁字 <a class="header-anchor" href="#_2-16-批3-补22-详情窗-200-仍裁字" aria-label="Permalink to &quot;2.16 批3-补22｜详情窗 200% 仍裁字&quot;">​</a></h3><ul><li><strong>前置</strong>：E0、C-DPI（200%）。</li><li><strong>步骤</strong>：200% 缩放下开任意组件详情窗，检查标题、正文、底部按钮区。</li><li><strong>预期</strong>：完整显示无裁切（Resize 补回非客户区差值：GetWindowRect−GetClientRect）。</li></ul><h3 id="_2-17-批3-补47-检查更新三行-失败降级" tabindex="-1">2.17 批3-补47｜检查更新三行 + 失败降级 <a class="header-anchor" href="#_2-17-批3-补47-检查更新三行-失败降级" aria-label="Permalink to &quot;2.17 批3-补47｜检查更新三行 + 失败降级&quot;">​</a></h3><ul><li><strong>前置</strong>：E0（2026-10-12 后的包）、C-DISCONNECT（断网/恢复手段）。</li><li><strong>步骤</strong>：① 打开设置 → 关于，点「检查更新」，等出结论；② 断网后再点一次「检查更新」；③ 恢复网络再点一次。有新版本时看「打开下载页」按钮是否出现并指向 releases/latest。</li><li><strong>预期</strong>：① 三行齐——当前版本 / 远程最新版本（tag_name）/ 检查结果（已是最新，或「有新版本 vN」+「打开下载页」），最后检查时间更新到分钟；② 断网显示「无法检查更新（HH:mm）」，不弹异常框；③ 恢复后恢复正常结论。</li></ul><hr><h2 id="_3-未修-53-条-代码就位-首验-其中-b-103-b-104-b-502-应用侧已于-2026-10-13-patrol-b-全量-ci-单测代验并在-todo-mvp-issues-勾账——本章保留对应条目仅作装机顺手复核步骤。计数口径-f2-与-f1-同账本行-不单计" tabindex="-1">3. 未修（53 条：代码就位，首验；其中 B-103/B-104/B-502 应用侧已于 2026-10-13 patrol-B 全量 CI/单测代验并在 todo/mvp-issues 勾账——本章保留对应条目仅作装机顺手复核步骤。计数口径：F2 与 F1 同账本行，不单计） <a class="header-anchor" href="#_3-未修-53-条-代码就位-首验-其中-b-103-b-104-b-502-应用侧已于-2026-10-13-patrol-b-全量-ci-单测代验并在-todo-mvp-issues-勾账——本章保留对应条目仅作装机顺手复核步骤。计数口径-f2-与-f1-同账本行-不单计" aria-label="Permalink to &quot;3. 未修（53 条：代码就位，首验；其中 B-103/B-104/B-502 应用侧已于 2026-10-13 patrol-B 全量 CI/单测代验并在 todo/mvp-issues 勾账——本章保留对应条目仅作装机顺手复核步骤。计数口径：F2 与 F1 同账本行，不单计）&quot;">​</a></h2><h3 id="a-安装与进程" tabindex="-1">A 安装与进程 <a class="header-anchor" href="#a-安装与进程" aria-label="Permalink to &quot;A 安装与进程&quot;">​</a></h3><h4 id="a1-b-101-二次启动不重复进程" tabindex="-1">A1｜B-101｜二次启动不重复进程 <a class="header-anchor" href="#a1-b-101-二次启动不重复进程" aria-label="Permalink to &quot;A1｜B-101｜二次启动不重复进程&quot;">​</a></h4><ul><li><strong>前置</strong>：E0。</li><li><strong>步骤</strong>：双击 exe 第二次启动。</li><li><strong>预期</strong>：不出现第二个进程；既有实例收到唤起并弹气泡提示。</li></ul><h4 id="a2-b-101-托盘驻留" tabindex="-1">A2｜B-101｜托盘驻留 <a class="header-anchor" href="#a2-b-101-托盘驻留" aria-label="Permalink to &quot;A2｜B-101｜托盘驻留&quot;">​</a></h4><ul><li><strong>前置</strong>：E0。</li><li><strong>步骤</strong>：关闭所有 Beacon 窗口 → 看任务管理器；再从托盘菜单 Exit。</li><li><strong>预期</strong>：关窗后进程驻留托盘；Exit 才真正退出、进程消失。</li></ul><h4 id="a3-批3-补271-托盘-explorer-重启恢复" tabindex="-1">A3｜批3-补27①｜托盘 Explorer 重启恢复 <a class="header-anchor" href="#a3-批3-补271-托盘-explorer-重启恢复" aria-label="Permalink to &quot;A3｜批3-补27①｜托盘 Explorer 重启恢复&quot;">​</a></h4><ul><li><strong>前置</strong>：E0，Beacon 运行中。</li><li><strong>步骤</strong>：任务管理器结束并重启 <code>explorer.exe</code>。</li><li><strong>预期</strong>：Explorer 恢复后托盘图标自回，级别色不丢。</li></ul><h4 id="a4-批3-补272-睡眠唤醒补刷" tabindex="-1">A4｜批3-补27②｜睡眠唤醒补刷 <a class="header-anchor" href="#a4-批3-补272-睡眠唤醒补刷" aria-label="Permalink to &quot;A4｜批3-补27②｜睡眠唤醒补刷&quot;">​</a></h4><ul><li><strong>前置</strong>：E0，至少一个组件。</li><li><strong>步骤</strong>：睡眠（或锁屏断网模拟）→ 唤醒 → 观察数据更新时间。</li><li><strong>预期</strong>：唤醒后 ≤1 个刷新周期出新数据（不依赖手动强刷）。</li></ul><h4 id="a5-批3-补28-胶囊右键直达设置" tabindex="-1">A5｜批3-补28｜胶囊右键直达设置 <a class="header-anchor" href="#a5-批3-补28-胶囊右键直达设置" aria-label="Permalink to &quot;A5｜批3-补28｜胶囊右键直达设置&quot;">​</a></h4><ul><li><strong>前置</strong>：E0。</li><li><strong>步骤</strong>：右键胶囊；再左键拖动、左键单击。</li><li><strong>预期</strong>：右键弹设置窗；拖动/单击开面板行为不受干扰。</li></ul><h4 id="a6-b-104-开机自启" tabindex="-1">A6｜B-104｜开机自启 <a class="header-anchor" href="#a6-b-104-开机自启" aria-label="Permalink to &quot;A6｜B-104｜开机自启&quot;">​</a></h4><ul><li><strong>前置</strong>：E0。</li><li><strong>步骤</strong>：设置里开自启 → 重启系统；再关自启 → 重启；最后卸载验证残留。</li><li><strong>预期</strong>：开→登录后自动启动；关→不再自启；卸载后无自启残留项。</li></ul><h4 id="a7-b-105-崩溃兜底" tabindex="-1">A7｜B-105｜崩溃兜底 <a class="header-anchor" href="#a7-b-105-崩溃兜底" aria-label="Permalink to &quot;A7｜B-105｜崩溃兜底&quot;">​</a></h4><ul><li><strong>前置</strong>：E0、E1。</li><li><strong>步骤</strong>：人为制造异常（配置指向会抛错的端点等）→ 观察进程与日志。</li><li><strong>预期</strong>：进程存活、日志含堆栈、无僵尸窗口。</li></ul><h4 id="a8-b-804-干净-vm-安装" tabindex="-1">A8｜B-804｜干净 VM 安装 <a class="header-anchor" href="#a8-b-804-干净-vm-安装" aria-label="Permalink to &quot;A8｜B-804｜干净 VM 安装&quot;">​</a></h4><ul><li><strong>前置</strong>：干净 Windows 11 虚拟机。</li><li><strong>步骤</strong>：下载 nightly → 运行 → 完成 B-803 脚本（见 <code>docs/acceptance-B803-e2e-walkthrough.md</code>）。</li><li><strong>预期</strong>：装得上、跑得起来、脚本走查通过。</li></ul><h4 id="a9-b-102-胶囊位置记忆-跨-dpi-无错乱" tabindex="-1">A9｜B-102｜胶囊位置记忆 / 跨 DPI 无错乱 <a class="header-anchor" href="#a9-b-102-胶囊位置记忆-跨-dpi-无错乱" aria-label="Permalink to &quot;A9｜B-102｜胶囊位置记忆 / 跨 DPI 无错乱&quot;">​</a></h4><ul><li><strong>前置</strong>：E0、C-DPI。</li><li><strong>步骤</strong>：① 拖胶囊到非默认位置 → 重启；② 跨不同缩放屏拖动。</li><li><strong>预期</strong>：重启后胶囊回到上次位置；跨 DPI 拖动无尺寸错乱（与 2.13/2.15 互证）。</li></ul><h4 id="a10-b-103-全局热键" tabindex="-1">A10｜B-103｜全局热键 <a class="header-anchor" href="#a10-b-103-全局热键" aria-label="Permalink to &quot;A10｜B-103｜全局热键&quot;">​</a></h4><ul><li><strong>前置</strong>：E0。</li><li><strong>步骤</strong>：① 在任意前台应用（记事本/浏览器/游戏全屏除外）按热键；② 设置改键 → 重启 → 用新键。</li><li><strong>预期</strong>：任意前台下热键生效打开面板；改键持久化且旧键失效、新键生效。</li></ul><h3 id="b-连接与组件数据源" tabindex="-1">B 连接与组件数据源 <a class="header-anchor" href="#b-连接与组件数据源" aria-label="Permalink to &quot;B 连接与组件数据源&quot;">​</a></h3><h4 id="b1-批3-补31-jenkins-构建卡" tabindex="-1">B1｜批3-补31｜Jenkins 构建卡 <a class="header-anchor" href="#b1-批3-补31-jenkins-构建卡" aria-label="Permalink to &quot;B1｜批3-补31｜Jenkins 构建卡&quot;">​</a></h4><ul><li><strong>前置</strong>：E0、C-JENKINS。</li><li><strong>步骤</strong>：建 Jenkins 连接（匿名或 user:apiToken）→ 测试 → 添加 <code>jenkins.build</code> 组件填 job_path。</li><li><strong>预期</strong>：构建灯/构建号随刷新走；构建中亮黄；成功绿/失败红（color 判级）。</li></ul><h4 id="b2-批3-补32-本机网络卡" tabindex="-1">B2｜批3-补32｜本机网络卡 <a class="header-anchor" href="#b2-批3-补32-本机网络卡" aria-label="Permalink to &quot;B2｜批3-补32｜本机网络卡&quot;">​</a></h4><ul><li><strong>前置</strong>：E0、C-MACHINE。</li><li><strong>步骤</strong>：建 machine 连接（零凭据）→ 添加 <code>machine.net</code> 组件 → 刷两次以上。</li><li><strong>预期</strong>：IP 与累计流量在 L3 可见；首刷无速率、第二刷起 ↓↑ 速率随刷新变化。</li></ul><h4 id="b3-批3-补33-本机-git-卡" tabindex="-1">B3｜批3-补33｜本机 Git 卡 <a class="header-anchor" href="#b3-批3-补33-本机-git-卡" aria-label="Permalink to &quot;B3｜批3-补33｜本机 Git 卡&quot;">​</a></h4><ul><li><strong>前置</strong>：E0、C-MACHINE、本机任一 Git 仓库路径。</li><li><strong>步骤</strong>：添加 <code>machine.git</code> 组件，repo_path 填本机仓库 → 刷新；再让本地落后远端（如 revert 一个远端已有 commit）。</li><li><strong>预期</strong>：↑↓/改动/stash 数随刷新走；落后远端亮黄。</li></ul><h4 id="b4-批3-补36-本机资源卡" tabindex="-1">B4｜批3-补36｜本机资源卡 <a class="header-anchor" href="#b4-批3-补36-本机资源卡" aria-label="Permalink to &quot;B4｜批3-补36｜本机资源卡&quot;">​</a></h4><ul><li><strong>前置</strong>：E0、C-MACHINE。</li><li><strong>步骤</strong>：添加 <code>machine.local</code> 组件 → 连续刷新；把 CPU 阈值调低（如 20）。</li><li><strong>预期</strong>：CPU 首刷不出数、第二刷起百分比随刷新走；内存/磁盘即时百分比；低于阈值时亮黄判级生效。</li></ul><h4 id="b5-批3-补34-mimo-整行-cookie" tabindex="-1">B5｜批3-补34｜MiMo 整行 Cookie <a class="header-anchor" href="#b5-批3-补34-mimo-整行-cookie" aria-label="Permalink to &quot;B5｜批3-补34｜MiMo 整行 Cookie&quot;">​</a></h4><ul><li><strong>前置</strong>：E0、C-MIMO。</li><li><strong>步骤</strong>：控制台凭据栏粘贴整行 Cookie（非单个 api-platform_ph 值）→ 刷新。</li><li><strong>预期</strong>：自动提取 api-platform_ph 并出数（此前整行粘贴卡 Offline）。</li></ul><h4 id="b6-批3-补381-mimo-401-明示-重录指引" tabindex="-1">B6｜批3-补38①｜MiMo 401 明示 + 重录指引 <a class="header-anchor" href="#b6-批3-补381-mimo-401-明示-重录指引" aria-label="Permalink to &quot;B6｜批3-补38①｜MiMo 401 明示 + 重录指引&quot;">​</a></h4><ul><li><strong>前置</strong>：E0、C-MIMO。</li><li><strong>步骤</strong>：故意填过期/乱写的控制台 Cookie → 刷新 → 看卡片失败原因行。</li><li><strong>预期</strong>：Degraded 卡面明示「Cookie 已失效或未录制」并给出重录指引原文（含 F12 → api-platform_ph 路径）。</li></ul><h4 id="b7-批3-补382-mimo-litellm-网关记账档" tabindex="-1">B7｜批3-补38②｜MiMo LiteLLM 网关记账档 <a class="header-anchor" href="#b7-批3-补382-mimo-litellm-网关记账档" aria-label="Permalink to &quot;B7｜批3-补38②｜MiMo LiteLLM 网关记账档&quot;">​</a></h4><ul><li><strong>前置</strong>：E0；本机 LiteLLM 网关<strong>已接 DB</strong>（现状 <code>no_db_connection</code> 是网关侧缺口——此项与网关侧整改绑定，未接 DB 前只验 Degraded 明示半）。</li><li><strong>步骤</strong>：Settings 录 <code>litellm_spend_url</code>（如 <code>http://127.0.0.1:4000/spend/logs</code>）→ 刷新。</li><li><strong>预期</strong>：网关有 DB 时卡显「本月已用 $X.XX（网关记账）」；未接 DB 时明示「LiteLLM 未接数据库」Degraded，不静默降档。</li></ul><h4 id="b8-批3-补42-yaml-provider-dsl-端到端" tabindex="-1">B8｜批3-补42｜YAML Provider DSL 端到端 <a class="header-anchor" href="#b8-批3-补42-yaml-provider-dsl-端到端" aria-label="Permalink to &quot;B8｜批3-补42｜YAML Provider DSL 端到端&quot;">​</a></h4><ul><li><strong>前置</strong>：E0、C-HTTP；写一个 DSL 文件（见 <code>docs/configuration.md</code>「Provider DSL」节示例）。</li><li><strong>步骤</strong>：① http 连接 Settings 配 <code>dsl_path</code> 指向声明文件 → 刷新 <code>http.status</code> 组件（widget.Config 不填数据键）；② 在 widget.Config 填同名键再刷新；③ 打开该组件详情页看动作区，点带 retry 的动作（让目标端点先失败一次）；④ 把 YAML 改坏（Tab 缩进）再刷新；⑤ 移走文件再刷新；⑥ 删掉 <code>dsl_path</code> 刷新。</li><li><strong>预期</strong>：① 按 DSL mapping 出数；② 实例值覆盖 DSL；③ DSL 动作仅出现在该连接的组件上，失败自动重试、最终失败消息带「已重试 N 次」；④ 卡面 Degraded 明示行号、启动不受影响、其他连接正常；⑤ 同样 Degraded 明示「文件不存在」；⑥ 行为与未用 DSL 的连接完全一致（零变化）。</li></ul><h4 id="b9-b-206-断网启动有数据" tabindex="-1">B9｜B-206｜断网启动有数据 <a class="header-anchor" href="#b9-b-206-断网启动有数据" aria-label="Permalink to &quot;B9｜B-206｜断网启动有数据&quot;">​</a></h4><ul><li><strong>前置</strong>：E0、至少一个出过数的组件、C-DISCONNECT。</li><li><strong>步骤</strong>：正常出数一次 → 退出 → 断网 → 启动。</li><li><strong>预期</strong>：界面有缓存数据并标注 Last update；随后恢复网络自动刷新出新数据（缓存水合全周期单测已过，本条验 UI 半）。</li></ul><h4 id="b10-批3-补351-herald-事件台账卡" tabindex="-1">B10｜批3-补35①｜Herald 事件台账卡 <a class="header-anchor" href="#b10-批3-补351-herald-事件台账卡" aria-label="Permalink to &quot;B10｜批3-补35①｜Herald 事件台账卡&quot;">​</a></h4><ul><li><strong>前置</strong>：E0、C-HERALD。</li><li><strong>步骤</strong>：建 herald 连接 → 添加 <code>herald.incidents</code> 组件 → 在 herald 侧制造/解决一条 open 事件。</li><li><strong>预期</strong>：未决计数随台账走；open 亮黄、critical 亮红；解决后归绿。</li></ul><h4 id="b11-批3-补352-herald-订阅卡" tabindex="-1">B11｜批3-补35②｜Herald 订阅卡 <a class="header-anchor" href="#b11-批3-补352-herald-订阅卡" aria-label="Permalink to &quot;B11｜批3-补35②｜Herald 订阅卡&quot;">​</a></h4><ul><li><strong>前置</strong>：E0、C-HERALD。</li><li><strong>步骤</strong>：添加 <code>herald.feed</code> 组件（公开类目或私密 token）→ 等新条目投递。</li><li><strong>预期</strong>：新条目未读数随刷新递增；token 走 DPAPI 不落明文。</li></ul><h4 id="b12-批3-补37-herald-投递失败卡" tabindex="-1">B12｜批3-补37｜Herald 投递失败卡 <a class="header-anchor" href="#b12-批3-补37-herald-投递失败卡" aria-label="Permalink to &quot;B12｜批3-补37｜Herald 投递失败卡&quot;">​</a></h4><ul><li><strong>前置</strong>：E0、C-HERALD。</li><li><strong>步骤</strong>：添加 <code>herald.deliveries</code> 组件 → 制造一次失败投递（停掉目标 provider 再 notify）。</li><li><strong>预期</strong>：无失败时显「无失败」；失败后亮黄并显示失败计数。</li></ul><h4 id="b13-b-301-补充-匿名连接降级-配套项-与-2-1-并验可跳-不计入-53" tabindex="-1">B13｜B-301 补充｜匿名连接降级（配套项，与 2.1 并验可跳，不计入 53） <a class="header-anchor" href="#b13-b-301-补充-匿名连接降级-配套项-与-2-1-并验可跳-不计入-53" aria-label="Permalink to &quot;B13｜B-301 补充｜匿名连接降级（配套项，与 2.1 并验可跳，不计入 53）&quot;">​</a></h4><ul><li><strong>前置</strong>：同 2.1。</li><li><strong>步骤</strong>：无 PAT 建 GitHub 连接看降级行为。</li><li><strong>预期</strong>：按匿名限额如实显示，不冒充已认证。（与 2.1 步骤②重合，可并验）</li></ul><h3 id="c-actions" tabindex="-1">C Actions <a class="header-anchor" href="#c-actions" aria-label="Permalink to &quot;C Actions&quot;">​</a></h3><h4 id="c1-b-401-action-失败-ui-反馈" tabindex="-1">C1｜B-401｜Action 失败 UI 反馈 <a class="header-anchor" href="#c1-b-401-action-失败-ui-反馈" aria-label="Permalink to &quot;C1｜B-401｜Action 失败 UI 反馈&quot;">​</a></h4><ul><li><strong>前置</strong>：E0；一个会失败的 Action（如 url 指向不通端口）。</li><li><strong>步骤</strong>：详情页点击该动作。</li><li><strong>预期</strong>：UI 有可见失败反馈（结果文本/颜色），不静默。</li></ul><h4 id="c2-b-402-浏览器打开-url" tabindex="-1">C2｜B-402｜浏览器打开 URL <a class="header-anchor" href="#c2-b-402-浏览器打开-url" aria-label="Permalink to &quot;C2｜B-402｜浏览器打开 URL&quot;">​</a></h4><ul><li><strong>前置</strong>：E0；带 DetailUrl 的组件。</li><li><strong>步骤</strong>：详情页点 Open。</li><li><strong>预期</strong>：默认浏览器打开正确 URL（模板渲染单测已过，本条验浏览器半）。</li></ul><h4 id="c3-b-403-workflow-dispatch-全程" tabindex="-1">C3｜B-403｜Workflow Dispatch 全程 <a class="header-anchor" href="#c3-b-403-workflow-dispatch-全程" aria-label="Permalink to &quot;C3｜B-403｜Workflow Dispatch 全程&quot;">​</a></h4><ul><li><strong>前置</strong>：E0、C-GH、有 dispatch 权限的仓库。</li><li><strong>步骤</strong>：dispatch 一个 workflow → 观察 Run→运行中→终态全程。</li><li><strong>预期</strong>：全程状态可在 Beacon 看到（无需开 GitHub 网页）。</li></ul><h4 id="c4-b-404-本机命令确认弹窗-超时落盘" tabindex="-1">C4｜B-404｜本机命令确认弹窗 + 超时落盘 <a class="header-anchor" href="#c4-b-404-本机命令确认弹窗-超时落盘" aria-label="Permalink to &quot;C4｜B-404｜本机命令确认弹窗 + 超时落盘&quot;">​</a></h4><ul><li><strong>前置</strong>：E0；配置一个 local.command 动作。</li><li><strong>步骤</strong>：① 触发动作看确认弹窗；② 配置一个长命令验证超时终止与日志落盘。</li><li><strong>预期</strong>：默认弹确认（可关按 Action 配置）；超时终止进程、输出仍落盘（执行器单测已过，本条验弹窗 UI 半）。</li></ul><h3 id="d-通知" tabindex="-1">D 通知 <a class="header-anchor" href="#d-通知" aria-label="Permalink to &quot;D 通知&quot;">​</a></h3><h4 id="d1-b-501-toast-全链路" tabindex="-1">D1｜B-501｜Toast 全链路 <a class="header-anchor" href="#d1-b-501-toast-全链路" aria-label="Permalink to &quot;D1｜B-501｜Toast 全链路&quot;">​</a></h4><ul><li><strong>前置</strong>：E0；通知规则命中。</li><li><strong>步骤</strong>：① 触发 Toast；② 点击 Toast；③ 删除 HKCU\\Software\\Classes\\AppUserModelId 下的 AUMID 注册键（带 CustomActivator）后重启应用重试。</li><li><strong>预期</strong>：发送/点击/激活路由全通；AUMID 注册缺失自愈（下次启动由 toolkit Initialize 重建注册键）。</li></ul><h4 id="d2-b-502-toast-冷却" tabindex="-1">D2｜B-502｜Toast 冷却 <a class="header-anchor" href="#d2-b-502-toast-冷却" aria-label="Permalink to &quot;D2｜B-502｜Toast 冷却&quot;">​</a></h4><ul><li><strong>前置</strong>：E0；同上。</li><li><strong>步骤</strong>：注入 Failed 状态（如把某连接指向坏端点触发 Error）。</li><li><strong>预期</strong>：收到且仅收到一条 Toast（冷却期内不重复轰炸）。</li></ul><h4 id="d3-b-503-托盘着色" tabindex="-1">D3｜B-503｜托盘着色 <a class="header-anchor" href="#d3-b-503-托盘着色" aria-label="Permalink to &quot;D3｜B-503｜托盘着色&quot;">​</a></h4><ul><li><strong>前置</strong>：E0；组件状态可控。</li><li><strong>步骤</strong>：制造 Warning/Error → 看托盘图标。</li><li><strong>预期</strong>：聚合状态变化 ≤1 个刷新周期内反映到托盘图标颜色。</li></ul><h4 id="d4-b-504-胶囊真实聚合" tabindex="-1">D4｜B-504｜胶囊真实聚合 <a class="header-anchor" href="#d4-b-504-胶囊真实聚合" aria-label="Permalink to &quot;D4｜B-504｜胶囊真实聚合&quot;">​</a></h4><ul><li><strong>前置</strong>：E0；组件状态可控。</li><li><strong>步骤</strong>：断网（C-DISCONNECT）看胶囊；恢复后核对计数。</li><li><strong>预期</strong>：断网显 Offline 横幅+时间；计数与实际 Widget 状态一致。</li></ul><h3 id="e-l2-l3" tabindex="-1">E L2 / L3 <a class="header-anchor" href="#e-l2-l3" aria-label="Permalink to &quot;E L2 / L3&quot;">​</a></h3><h4 id="e1-b-601-quick-panel-开关" tabindex="-1">E1｜B-601｜Quick Panel 开关 <a class="header-anchor" href="#e1-b-601-quick-panel-开关" aria-label="Permalink to &quot;E1｜B-601｜Quick Panel 开关&quot;">​</a></h4><ul><li><strong>前置</strong>：E0。</li><li><strong>步骤</strong>：热键开面板 → ESC 关 → 点面板外失焦关；纯键盘 Tab/方向键遍历后关闭；连开多次。</li><li><strong>预期</strong>：打开 &lt;100ms 无白屏（缓存优先）；键盘可完整操作关闭；重复开关稳定。</li></ul><h4 id="e2-b-602-overview-pin-落库" tabindex="-1">E2｜B-602｜Overview/Pin 落库 <a class="header-anchor" href="#e2-b-602-overview-pin-落库" aria-label="Permalink to &quot;E2｜B-602｜Overview/Pin 落库&quot;">​</a></h4><ul><li><strong>前置</strong>：E0。</li><li><strong>步骤</strong>：对比 Overview 计数与实际状态；右键 Pin 一个组件 → 重启。</li><li><strong>预期</strong>：计数/事件一致；Pin 落库（本阶段无 L0 UI 效果也要落 widgets.json/pins.json）。</li></ul><h4 id="e3-b-603-detail-retry-链路" tabindex="-1">E3｜B-603｜Detail + Retry 链路 <a class="header-anchor" href="#e3-b-603-detail-retry-链路" aria-label="Permalink to &quot;E3｜B-603｜Detail + Retry 链路&quot;">​</a></h4><ul><li><strong>前置</strong>：E0；有失败 job 的 run。</li><li><strong>步骤</strong>：L2 事件一键打开详情 → 点 [Retry]。</li><li><strong>预期</strong>：详情直达对应对象；Retry 全链路可用（含确认与结果反馈）。</li></ul><h3 id="f-l0-tile-行为" tabindex="-1">F L0 tile 行为 <a class="header-anchor" href="#f-l0-tile-行为" aria-label="Permalink to &quot;F L0 tile 行为&quot;">​</a></h3><h4 id="f1-b-7011-点击不断焦点" tabindex="-1">F1｜B-701①｜点击不断焦点 <a class="header-anchor" href="#f1-b-7011-点击不断焦点" aria-label="Permalink to &quot;F1｜B-701①｜点击不断焦点&quot;">​</a></h4><ul><li><strong>前置</strong>：E0；L0 悬浮 tile（设置开关或 Pin）。</li><li><strong>步骤</strong>：聚焦某前台应用（如记事本）→ 点击 tile。</li><li><strong>预期</strong>：当前应用焦点不被打断（可继续打字）。</li></ul><h4 id="f2-b-7011b-空白点击落桌面-与-f1-同属台账条-1" tabindex="-1">F2｜B-701①b｜空白点击落桌面（与 F1 同属台账条 1） <a class="header-anchor" href="#f2-b-7011b-空白点击落桌面-与-f1-同属台账条-1" aria-label="Permalink to &quot;F2｜B-701①b｜空白点击落桌面（与 F1 同属台账条 1）&quot;">​</a></h4><ul><li><strong>前置</strong>：同 F1。</li><li><strong>步骤</strong>：点击 tile 窗口空白区域。</li><li><strong>预期</strong>：点击穿透落到桌面（不吃点击）。</li></ul><h4 id="f3-b-7012-两-tile-独立更新" tabindex="-1">F3｜B-701②｜两 tile 独立更新 <a class="header-anchor" href="#f3-b-7012-两-tile-独立更新" aria-label="Permalink to &quot;F3｜B-701②｜两 tile 独立更新&quot;">​</a></h4><ul><li><strong>前置</strong>：两个不同源组件的 tile。</li><li><strong>步骤</strong>：只让一个源状态变化。</li><li><strong>预期</strong>：两 tile 状态各自独立更新；窗口不进任务栏/Alt-Tab。</li></ul><h4 id="f4-b-7013-悬浮形态拖放还原" tabindex="-1">F4｜B-701③｜悬浮形态拖放还原 <a class="header-anchor" href="#f4-b-7013-悬浮形态拖放还原" aria-label="Permalink to &quot;F4｜B-701③｜悬浮形态拖放还原&quot;">​</a></h4><ul><li><strong>前置</strong>：悬浮形态开启。</li><li><strong>步骤</strong>：拖放 tile → 重启。</li><li><strong>预期</strong>：每组件一窗可拖放；重启后位置还原；与宿主面板二选一（互斥）。</li></ul><h4 id="f5-b-7021-pin-双入口一致" tabindex="-1">F5｜B-702①｜Pin 双入口一致 <a class="header-anchor" href="#f5-b-7021-pin-双入口一致" aria-label="Permalink to &quot;F5｜B-702①｜Pin 双入口一致&quot;">​</a></h4><ul><li><strong>前置</strong>：E0。</li><li><strong>步骤</strong>：分别经设置开关与右键菜单 Pin/取消同一组件。</li><li><strong>预期</strong>：两入口行为一致并持久化。</li></ul><h4 id="f6-b-7022-非准入不可钉" tabindex="-1">F6｜B-702②｜非准入不可钉 <a class="header-anchor" href="#f6-b-7022-非准入不可钉" aria-label="Permalink to &quot;F6｜B-702②｜非准入不可钉&quot;">​</a></h4><ul><li><strong>前置</strong>：E0。</li><li><strong>步骤</strong>：对非 PinSupported 类型（如 claude.usage 类本机卡）在两处入口尝试钉。</li><li><strong>预期</strong>：两处入口均不可钉（策略单测已过，本条验 UI 门控）。</li></ul><h4 id="f7-b-7031-位置-收起态还原-拔插显示器" tabindex="-1">F7｜B-703①｜位置/收起态还原 + 拔插显示器 <a class="header-anchor" href="#f7-b-7031-位置-收起态还原-拔插显示器" aria-label="Permalink to &quot;F7｜B-703①｜位置/收起态还原 + 拔插显示器&quot;">​</a></h4><ul><li><strong>前置</strong>：L0 tile 两块以上。</li><li><strong>步骤</strong>：拖位、收起 → 重启；再拔掉 tile 所在显示器 → 接回。</li><li><strong>预期</strong>：重启后位置/收起态还原；拔插后 tile 不丢（回收或回归可见区）。</li></ul><h4 id="f8-b-7032-跨-dpi-拖放与回收" tabindex="-1">F8｜B-703②｜跨 DPI 拖放与回收 <a class="header-anchor" href="#f8-b-7032-跨-dpi-拖放与回收" aria-label="Permalink to &quot;F8｜B-703②｜跨 DPI 拖放与回收&quot;">​</a></h4><ul><li><strong>前置</strong>：C-DPI 多屏。</li><li><strong>步骤</strong>：跨 DPI 显示器拖 tile；把副屏分辨率调小。</li><li><strong>预期</strong>：拖放尺寸正确（DpiLayoutMath 唯一口径）；分辨率变小后 tile 被回收到可见区。</li></ul><h4 id="f9-b-704-断网自愈" tabindex="-1">F9｜B-704｜断网自愈 <a class="header-anchor" href="#f9-b-704-断网自愈" aria-label="Permalink to &quot;F9｜B-704｜断网自愈&quot;">​</a></h4><ul><li><strong>前置</strong>：L0 tile；C-DISCONNECT。</li><li><strong>步骤</strong>：断网观察全流程 → 恢复。</li><li><strong>预期</strong>：全程无任何弹窗（只 Offline 态）；恢复后 tile 自愈出新数据（socket 级集成测试已过，本条验 UI 半）。</li></ul><h4 id="f10-b-7051-critical-仅脉冲" tabindex="-1">F10｜B-705①｜Critical 仅脉冲 <a class="header-anchor" href="#f10-b-7051-critical-仅脉冲" aria-label="Permalink to &quot;F10｜B-705①｜Critical 仅脉冲&quot;">​</a></h4><ul><li><strong>前置</strong>：E0；注入 Critical（阈值调极端或造 Error+ 状态）。</li><li><strong>步骤</strong>：注入后观察 L0。</li><li><strong>预期</strong>：L0 仅变色+脉冲，无打断（不弹窗不抢焦点）；Toast 照常由通知引擎发出。</li></ul><h4 id="f11-b-7052-rfc-§6-2-7-四条清单" tabindex="-1">F11｜B-705②｜RFC §6.2.7 四条清单 <a class="header-anchor" href="#f11-b-7052-rfc-§6-2-7-四条清单" aria-label="Permalink to &quot;F11｜B-705②｜RFC §6.2.7 四条清单&quot;">​</a></h4><ul><li><strong>前置</strong>：同 F10。</li><li><strong>步骤</strong>：逐条执行 <code>docs/acceptance-B705-L0-behavior.md</code> 的四条清单并记录。</li><li><strong>预期</strong>：四条全过并留记录。</li></ul><h3 id="g-外观与动效" tabindex="-1">G 外观与动效 <a class="header-anchor" href="#g-外观与动效" aria-label="Permalink to &quot;G 外观与动效&quot;">​</a></h3><h4 id="g1-b-7061-级别色三面同步" tabindex="-1">G1｜B-706①｜级别色三面同步 <a class="header-anchor" href="#g1-b-7061-级别色三面同步" aria-label="Permalink to &quot;G1｜B-706①｜级别色三面同步&quot;">​</a></h4><ul><li><strong>前置</strong>：E0；L0 tile + 胶囊 + 托盘同时可见。</li><li><strong>步骤</strong>：设置改某级别色（如 Warning 改橙）。</li><li><strong>预期</strong>：L0 tile、胶囊、托盘图标三面同步变色。</li></ul><h4 id="g2-b-7062-coloroverride-单-tile" tabindex="-1">G2｜B-706②｜colorOverride 单 tile <a class="header-anchor" href="#g2-b-7062-coloroverride-单-tile" aria-label="Permalink to &quot;G2｜B-706②｜colorOverride 单 tile&quot;">​</a></h4><ul><li><strong>前置</strong>：两个以上 tile。</li><li><strong>步骤</strong>：仅给某 Widget 设 colorOverride。</li><li><strong>预期</strong>：仅该 tile 变色；优先级 Widget &gt; 级别 &gt; 默认正确。</li></ul><h4 id="g3-b-7063-非法颜色回退" tabindex="-1">G3｜B-706③｜非法颜色回退 <a class="header-anchor" href="#g3-b-7063-非法颜色回退" aria-label="Permalink to &quot;G3｜B-706③｜非法颜色回退&quot;">​</a></h4><ul><li><strong>前置</strong>：同 G2。</li><li><strong>步骤</strong>：填非法色值（如 <code>#GGG</code>）→ 重启。</li><li><strong>预期</strong>：回退默认色不崩溃；重启后保持回退态。</li></ul><h4 id="g4-b-7071-变色过渡" tabindex="-1">G4｜B-707①｜变色过渡 <a class="header-anchor" href="#g4-b-7071-变色过渡" aria-label="Permalink to &quot;G4｜B-707①｜变色过渡&quot;">​</a></h4><ul><li><strong>前置</strong>：动效档 reduced。</li><li><strong>步骤</strong>：制造 Success→Error 变化。</li><li><strong>预期</strong>：平滑变色过渡（非瞬跳）。</li></ul><h4 id="g5-b-7072-critical-脉冲三档" tabindex="-1">G5｜B-707②｜Critical 脉冲三档 <a class="header-anchor" href="#g5-b-7072-critical-脉冲三档" aria-label="Permalink to &quot;G5｜B-707②｜Critical 脉冲三档&quot;">​</a></h4><ul><li><strong>前置</strong>：动效设置页。</li><li><strong>步骤</strong>：默认档看脉冲；off 档看全静止；full 档看呼吸灯并调强度。</li><li><strong>预期</strong>：脉冲默认开；off 全静止；full 呼吸灯可见且强度可调。</li></ul><h4 id="g6-b-7073-动效边界" tabindex="-1">G6｜B-707③｜动效边界 <a class="header-anchor" href="#g6-b-7073-动效边界" aria-label="Permalink to &quot;G6｜B-707③｜动效边界&quot;">​</a></h4><ul><li><strong>前置</strong>：动效开启。</li><li><strong>步骤</strong>：动效期间听声/试抢焦点；隐藏/收起 tile 后查功耗（任务管理器 CPU/GPU）。</li><li><strong>预期</strong>：不抢焦点、不发声；隐藏/收起时无动画循环（功耗回落）。</li></ul><h3 id="h-导入导出与设置" tabindex="-1">H 导入导出与设置 <a class="header-anchor" href="#h-导入导出与设置" aria-label="Permalink to &quot;H 导入导出与设置&quot;">​</a></h3><h4 id="h1-b-802-导入导出端到端" tabindex="-1">H1｜B-802｜导入导出端到端 <a class="header-anchor" href="#h1-b-802-导入导出端到端" aria-label="Permalink to &quot;H1｜B-802｜导入导出端到端&quot;">​</a></h4><ul><li><strong>前置</strong>：E0；配好凭据的实例。</li><li><strong>步骤</strong>：导出 → 全文搜 token；在另一目录（或 VM）导入 → 重录密钥 → 对比行为。</li><li><strong>预期</strong>：导出文件全文无 token（JSON 只存 credentialRef，secrets 不打包）；导入+重录后与原机行为一致（存储层 5 例已过，本条验端到端）。</li></ul><h4 id="h2-b-8051-调色-动效即时预览持久化" tabindex="-1">H2｜B-805①｜调色/动效即时预览持久化 <a class="header-anchor" href="#h2-b-8051-调色-动效即时预览持久化" aria-label="Permalink to &quot;H2｜B-805①｜调色/动效即时预览持久化&quot;">​</a></h4><ul><li><strong>前置</strong>：E0。</li><li><strong>步骤</strong>：改色/改档 → 看即时预览 → 重启。</li><li><strong>预期</strong>：改动即时生效并持久化，重启后仍在。</li></ul><h4 id="h3-b-8052-重置默认-off-档" tabindex="-1">H3｜B-805②｜重置默认 + off 档 <a class="header-anchor" href="#h3-b-8052-重置默认-off-档" aria-label="Permalink to &quot;H3｜B-805②｜重置默认 + off 档&quot;">​</a></h4><ul><li><strong>前置</strong>：同 H2。</li><li><strong>步骤</strong>：点重置默认；选 off 档看预览。</li><li><strong>预期</strong>：一键还原默认；off 档预览即全静止。</li></ul><h3 id="i-总验收" tabindex="-1">I 总验收 <a class="header-anchor" href="#i-总验收" aria-label="Permalink to &quot;I 总验收&quot;">​</a></h3><h4 id="i1-b-803-mvp-全流程走查" tabindex="-1">I1｜B-803｜MVP 全流程走查 <a class="header-anchor" href="#i1-b-803-mvp-全流程走查" aria-label="Permalink to &quot;I1｜B-803｜MVP 全流程走查&quot;">​</a></h4><ul><li><strong>前置</strong>：前述全部（或抽样关键项）通过。</li><li><strong>步骤</strong>：按任务书 §成功标准录屏/截图，归档 <code>docs/</code>（脚本见 <code>docs/acceptance-B803-e2e-walkthrough.md</code>）。</li><li><strong>预期</strong>：全程录屏归档；发现问题全部修复或开 Issue。</li></ul><h4 id="i2-sha256-与时间戳核对-配套项-不计入-53" tabindex="-1">I2｜SHA256 与时间戳核对（配套项，不计入 53） <a class="header-anchor" href="#i2-sha256-与时间戳核对-配套项-不计入-53" aria-label="Permalink to &quot;I2｜SHA256 与时间戳核对（配套项，不计入 53）&quot;">​</a></h4><ul><li><strong>前置</strong>：E0。</li><li><strong>步骤</strong>：下载页哈希与本地 zip 比对。</li><li><strong>预期</strong>：一致（发布断言已核，本条为装机侧复核）。</li></ul><hr><h2 id="附-本地自动化覆盖注记-2026-10-10-分诊-commit-4b04205-批3-补39-42-45-47-48-49-增补-当前-991-991-绿" tabindex="-1">附：本地自动化覆盖注记（2026-10-10 分诊 commit 4b04205 + 批3-补39/42/45/47/48/49 增补，当前 991/991 绿） <a class="header-anchor" href="#附-本地自动化覆盖注记-2026-10-10-分诊-commit-4b04205-批3-补39-42-45-47-48-49-增补-当前-991-991-绿" aria-label="Permalink to &quot;附：本地自动化覆盖注记（2026-10-10 分诊 commit 4b04205 + 批3-补39/42/45/47/48/49 增补，当前 991/991 绿）&quot;">​</a></h2><p>Windows 运行时表现以本清单装机走查为准；以下记录本机已证面，回执时避免重复排查：</p><ul><li><strong>已勾两项（本地自动化全证）</strong>： <ul><li>B-801：SerializationRoundTripTests（AppConfig 全字段往返+默认值不变式）+ JsonConfigurationStoreTests.AppConfig_AllFields_SurviveSaveAndReload（启动路径逐字段比对）+ token 不落 JSON 单测（DpapiSecretStore/ImportExport）。</li><li>B-207：OutageRecoveryIntegrationTests——真 HttpClient 连接拒绝→Offline+陈旧态（旧缓存保留）；恢复自动复位；RefreshWidgetAsync 返回 false 不抛；首错无缓存→「拉取失败」直显。</li></ul></li><li><strong>未勾项的本地半（UI/交互半需真机，维持挂账不代验）</strong>： <ul><li>B-706×3：PaletteResolverTests（优先级 Widget&gt;级别&gt;默认/非法值回退/offline 键）——变色联动与持久化 UI 半待真机。</li><li>B-702 第二条：WidgetDisplayPolicyTests.PanelCarries_NonPinSupported_NeverCarried——两处入口交互待真机。</li><li>B-703 几何：PinLayoutMathTests（锚点/DPI/越界回收/拓扑判定）——拖放与拔插显示器待真机。</li><li>B-207 分支补充：WidgetHostTests 假 Handler（Degraded/退避/健康去重）。</li><li>B-301/B-302/B-303：GitHubApiClient/GitHubPullRequests/GitHubActions 假 Handler 全分支（批3-补14/15）——真实凭据与真实仓库半待真机。</li><li>B-401/B-404：ActionRunnerTests 15 例（路由/确认/超时/取消/重试六态）+ LocalCommandExecutorTests（超时杀进程+落盘）——弹窗与反馈 UI 半待真机。</li><li>批3-补42 DSL：ProviderDslTests 46 例（解析/校验/缓存/MappingValue/端到端）+ ActionRunner 重试 6 例——dsl_path 真机配置与动作点击半待真机。</li><li>批3-补47 检查更新：UpdateCheckTests 48 例（版本解析形态与拒绝表、SemVer 12 组比较含预发布规则、Evaluate 含 nightly 日期口径、限流降级体）——GitHub 真端点半（三行展示、按钮语义、断网降级）待真机。</li><li>批3-补48 tile 字宽预算 + 多窗口额度：TileSizingTests 32 例（字宽模型逐类/每类型最坏值行→合计宽/标签优先级对齐 PinTile/machine show 联动）+ WidgetValueHintTests 多窗口 8 例（三窗/双窗/乱序/剩余口径/单窗不进/读数收起判定）——真机悬浮框数值列不再裁字的目视半待装机走查。</li></ul></li></ul>',171)])])}const b=l(a,[["render",e]]);export{c as __pageData,b as default};
